CREATE TABLE IF NOT EXISTS "users" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Login identity and the address alerts are delivered to.
	"email" VARCHAR(320) NOT NULL UNIQUE,
	-- Display name on assignments and status changes.
	"full_name" VARCHAR(160) NOT NULL,
	-- False when someone leaves. Their resolutions and comments keep their attribution.
	"is_active" BOOLEAN NOT NULL DEFAULT true,
	-- Account creation time.
	"created_at" TIMESTAMPTZ NOT NULL DEFAULT now(),
	PRIMARY KEY("id")
);

COMMENT ON TABLE "users" IS 'A person who triages errors. Deactivated rather than deleted, because every issue state change points back here.';
COMMENT ON COLUMN "users"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "users"."email" IS 'Login identity and the address alerts are delivered to.';
COMMENT ON COLUMN "users"."full_name" IS 'Display name on assignments and status changes.';
COMMENT ON COLUMN "users"."is_active" IS 'False when someone leaves. Their resolutions and comments keep their attribution.';
COMMENT ON COLUMN "users"."created_at" IS 'Account creation time.';

CREATE TABLE IF NOT EXISTS "projects" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- URL identifier used in the dashboard and in the ingestion endpoint.
	"slug" VARCHAR(80) NOT NULL UNIQUE,
	-- Display name.
	"name" VARCHAR(160) NOT NULL,
	-- javascript | python | java | go | ruby | php | other. Decides how a stack trace is symbolicated and rendered, not how it is stored.
	"platform" VARCHAR(40) NOT NULL DEFAULT 'other',
	-- Public key embedded in the client SDK. Public by design, which is why it only grants write access to this one project.
	"ingest_key" VARCHAR(64) NOT NULL UNIQUE,
	-- Server-side share of events kept, in basis points. Applied after grouping so an issue is never lost entirely, only thinned.
	"sample_rate_bps" INTEGER NOT NULL DEFAULT 10000,
	-- How long raw events are kept. Issues outlive their events, which is why counters live on the issue rather than being derived.
	"retention_days" SMALLINT NOT NULL DEFAULT 90,
	-- Creation time.
	"created_at" TIMESTAMPTZ NOT NULL DEFAULT now(),
	PRIMARY KEY("id")
);

COMMENT ON TABLE "projects" IS 'The unit of ownership, alerting and quota. One deployable service per project, because everything here — fingerprints, releases, alert rules — is scoped to a codebase.';
COMMENT ON COLUMN "projects"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "projects"."slug" IS 'URL identifier used in the dashboard and in the ingestion endpoint.';
COMMENT ON COLUMN "projects"."name" IS 'Display name.';
COMMENT ON COLUMN "projects"."platform" IS 'javascript | python | java | go | ruby | php | other. Decides how a stack trace is symbolicated and rendered, not how it is stored.';
COMMENT ON COLUMN "projects"."ingest_key" IS 'Public key embedded in the client SDK. Public by design, which is why it only grants write access to this one project.';
COMMENT ON COLUMN "projects"."sample_rate_bps" IS 'Server-side share of events kept, in basis points. Applied after grouping so an issue is never lost entirely, only thinned.';
COMMENT ON COLUMN "projects"."retention_days" IS 'How long raw events are kept. Issues outlive their events, which is why counters live on the issue rather than being derived.';
COMMENT ON COLUMN "projects"."created_at" IS 'Creation time.';

CREATE TABLE IF NOT EXISTS "releases" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Owning project.
	"project_id" BIGINT NOT NULL,
	-- Version string reported by the SDK, usually a commit sha or a semver tag.
	"version" VARCHAR(255) NOT NULL,
	-- Monotonic sequence assigned at creation. Regression detection compares ordinals because version strings do not sort: 1.10.0 is after 1.9.0 only if someone parses it.
	"ordinal" BIGINT NOT NULL,
	-- Source revision, used to link a stack frame to a line of code.
	"commit_sha" VARCHAR(64),
	-- Deploy time. Null while a release is created but not yet rolled out.
	"released_at" TIMESTAMPTZ,
	-- When the release was first seen or registered.
	"created_at" TIMESTAMPTZ NOT NULL DEFAULT now(),
	PRIMARY KEY("id")
);

COMMENT ON TABLE "releases" IS 'A deployed version of the code. It is the axis regressions and adoption are measured on, and the reason an issue can say which build first broke and which build fixed it.';
COMMENT ON COLUMN "releases"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "releases"."project_id" IS 'Owning project.';
COMMENT ON COLUMN "releases"."version" IS 'Version string reported by the SDK, usually a commit sha or a semver tag.';
COMMENT ON COLUMN "releases"."ordinal" IS 'Monotonic sequence assigned at creation. Regression detection compares ordinals because version strings do not sort: 1.10.0 is after 1.9.0 only if someone parses it.';
COMMENT ON COLUMN "releases"."commit_sha" IS 'Source revision, used to link a stack frame to a line of code.';
COMMENT ON COLUMN "releases"."released_at" IS 'Deploy time. Null while a release is created but not yet rolled out.';
COMMENT ON COLUMN "releases"."created_at" IS 'When the release was first seen or registered.';

CREATE UNIQUE INDEX "uq_releases_project_version"
ON "releases" ("project_id", "version");
CREATE INDEX "idx_releases_project_ordinal"
ON "releases" ("project_id", "ordinal");

CREATE TABLE IF NOT EXISTS "issues" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Owning project. Fingerprints are only unique within a project, so the same library bug in two services stays two issues with two owners.
	"project_id" BIGINT NOT NULL,
	-- Hash of the grouping inputs — exception type, normalised message and the in-app portion of the stack. The unique index on it is what turns a flood of identical events into one row.
	"fingerprint" CHAR(40) NOT NULL,
	-- Exception type and message from the first event, kept denormalised so the issue list renders without touching events.
	"title" VARCHAR(500) NOT NULL,
	-- Function or route blamed for the error, taken from the topmost in-app frame.
	"culprit" VARCHAR(500),
	-- debug | info | warning | error | fatal. Highest level seen, so a warning that later crashes escalates the whole issue.
	"level" VARCHAR(16) NOT NULL DEFAULT 'error',
	-- unresolved | resolved | ignored. Ignored is distinct from resolved: it suppresses alerts without claiming the bug is fixed.
	"status" VARCHAR(16) NOT NULL DEFAULT 'unresolved',
	-- Snooze expiry. Null for a permanent ignore. The sweeper flips these back to unresolved, which is why the state is a timestamp and not a boolean.
	"ignored_until" TIMESTAMPTZ,
	-- First occurrence ever. Survives event retention, which is why it is stored rather than computed.
	"first_seen_at" TIMESTAMPTZ NOT NULL DEFAULT now(),
	-- Most recent occurrence. Drives sorting and the is-this-still-happening question.
	"last_seen_at" TIMESTAMPTZ NOT NULL DEFAULT now(),
	-- Total occurrences including events discarded by sampling. Incremented by the ingest path with the sample weight, so the count is honest even when the events are not all stored.
	"times_seen" BIGINT NOT NULL DEFAULT 0,
	-- Approximate distinct users hit, maintained from a sketch rather than counted. Severity is about how many people, not how many times.
	"users_affected" BIGINT NOT NULL DEFAULT 0,
	-- Release the issue was first seen in. Null for events that reported no release.
	"first_release_id" BIGINT,
	-- Release the fix shipped in. An event from a strictly later release is what defines a regression.
	"resolved_in_release_id" BIGINT,
	-- When it was marked resolved.
	"resolved_at" TIMESTAMPTZ,
	-- When it came back after being resolved. Kept separately from status so the issue list can show returned rather than merely unresolved.
	"regressed_at" TIMESTAMPTZ,
	PRIMARY KEY("id")
);

COMMENT ON TABLE "issues" IS 'The centrepiece: a deduplicated bug, not an occurrence. Everything a human acts on — status, assignment, alerting, ownership — hangs here, and events are evidence attached to it.';
COMMENT ON COLUMN "issues"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "issues"."project_id" IS 'Owning project. Fingerprints are only unique within a project, so the same library bug in two services stays two issues with two owners.';
COMMENT ON COLUMN "issues"."fingerprint" IS 'Hash of the grouping inputs — exception type, normalised message and the in-app portion of the stack. The unique index on it is what turns a flood of identical events into one row.';
COMMENT ON COLUMN "issues"."title" IS 'Exception type and message from the first event, kept denormalised so the issue list renders without touching events.';
COMMENT ON COLUMN "issues"."culprit" IS 'Function or route blamed for the error, taken from the topmost in-app frame.';
COMMENT ON COLUMN "issues"."level" IS 'debug | info | warning | error | fatal. Highest level seen, so a warning that later crashes escalates the whole issue.';
COMMENT ON COLUMN "issues"."status" IS 'unresolved | resolved | ignored. Ignored is distinct from resolved: it suppresses alerts without claiming the bug is fixed.';
COMMENT ON COLUMN "issues"."ignored_until" IS 'Snooze expiry. Null for a permanent ignore. The sweeper flips these back to unresolved, which is why the state is a timestamp and not a boolean.';
COMMENT ON COLUMN "issues"."first_seen_at" IS 'First occurrence ever. Survives event retention, which is why it is stored rather than computed.';
COMMENT ON COLUMN "issues"."last_seen_at" IS 'Most recent occurrence. Drives sorting and the is-this-still-happening question.';
COMMENT ON COLUMN "issues"."times_seen" IS 'Total occurrences including events discarded by sampling. Incremented by the ingest path with the sample weight, so the count is honest even when the events are not all stored.';
COMMENT ON COLUMN "issues"."users_affected" IS 'Approximate distinct users hit, maintained from a sketch rather than counted. Severity is about how many people, not how many times.';
COMMENT ON COLUMN "issues"."first_release_id" IS 'Release the issue was first seen in. Null for events that reported no release.';
COMMENT ON COLUMN "issues"."resolved_in_release_id" IS 'Release the fix shipped in. An event from a strictly later release is what defines a regression.';
COMMENT ON COLUMN "issues"."resolved_at" IS 'When it was marked resolved.';
COMMENT ON COLUMN "issues"."regressed_at" IS 'When it came back after being resolved. Kept separately from status so the issue list can show returned rather than merely unresolved.';

CREATE UNIQUE INDEX "uq_issues_project_fingerprint"
ON "issues" ("project_id", "fingerprint");
CREATE INDEX "idx_issues_project_status_seen"
ON "issues" ("project_id", "status", "last_seen_at");
CREATE INDEX "idx_issues_project_volume"
ON "issues" ("project_id", "times_seen");

CREATE TABLE IF NOT EXISTS "events" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Identifier generated by the client. Unique so a retried upload after a network timeout is a no-op instead of a duplicate.
	"event_id" UUID NOT NULL UNIQUE,
	-- Issue this event was grouped into. Assigned at ingest, before the event is durably stored, so grouping never depends on a later batch job.
	"issue_id" BIGINT NOT NULL,
	-- Denormalised from the issue so retention deletion and quota accounting scan one table.
	"project_id" BIGINT NOT NULL,
	-- Release the code was running. Null when the SDK reports no version, which is common in development.
	"release_id" BIGINT,
	-- production | staging | development or anything the SDK sends. A plain column rather than a table, because it is a free-form label the client controls.
	"environment" VARCHAR(64) NOT NULL DEFAULT 'production',
	-- Rendered exception message for this specific occurrence, including the values the issue title strips out.
	"message" TEXT,
	-- Host that produced the event, for spotting an error confined to one bad machine.
	"server_name" VARCHAR(255),
	-- Pseudonymous identifier of the affected end user. Null for events with no session, and the input to the users-affected estimate.
	"user_key" VARCHAR(255),
	-- URL or entry point being handled, the single most useful field for reproducing a web error.
	"request_url" VARCHAR(1000),
	-- Everything the SDK sent that is not searched on: runtime versions, device info, custom context. Kept as one blob so adding a field is an SDK change and not a migration.
	"context" JSONB,
	-- How many occurrences this stored event stands for. Ingest discards events above the project sample rate but folds their count into this weight and into issues.times_seen.
	"sample_weight" INTEGER NOT NULL DEFAULT 1,
	-- Client clock time of the error, which is what a timeline needs.
	"occurred_at" TIMESTAMPTZ NOT NULL,
	-- Server receipt time. The gap against occurred_at exposes offline buffering and clock skew.
	"received_at" TIMESTAMPTZ NOT NULL DEFAULT now(),
	PRIMARY KEY("id")
);

COMMENT ON TABLE "events" IS 'One raw occurrence. Events are high volume and short lived; they are deleted on the retention schedule while the issue and its counters remain, which is why no user-facing number is computed by counting rows here.';
COMMENT ON COLUMN "events"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "events"."event_id" IS 'Identifier generated by the client. Unique so a retried upload after a network timeout is a no-op instead of a duplicate.';
COMMENT ON COLUMN "events"."issue_id" IS 'Issue this event was grouped into. Assigned at ingest, before the event is durably stored, so grouping never depends on a later batch job.';
COMMENT ON COLUMN "events"."project_id" IS 'Denormalised from the issue so retention deletion and quota accounting scan one table.';
COMMENT ON COLUMN "events"."release_id" IS 'Release the code was running. Null when the SDK reports no version, which is common in development.';
COMMENT ON COLUMN "events"."environment" IS 'production | staging | development or anything the SDK sends. A plain column rather than a table, because it is a free-form label the client controls.';
COMMENT ON COLUMN "events"."message" IS 'Rendered exception message for this specific occurrence, including the values the issue title strips out.';
COMMENT ON COLUMN "events"."server_name" IS 'Host that produced the event, for spotting an error confined to one bad machine.';
COMMENT ON COLUMN "events"."user_key" IS 'Pseudonymous identifier of the affected end user. Null for events with no session, and the input to the users-affected estimate.';
COMMENT ON COLUMN "events"."request_url" IS 'URL or entry point being handled, the single most useful field for reproducing a web error.';
COMMENT ON COLUMN "events"."context" IS 'Everything the SDK sent that is not searched on: runtime versions, device info, custom context. Kept as one blob so adding a field is an SDK change and not a migration.';
COMMENT ON COLUMN "events"."sample_weight" IS 'How many occurrences this stored event stands for. Ingest discards events above the project sample rate but folds their count into this weight and into issues.times_seen.';
COMMENT ON COLUMN "events"."occurred_at" IS 'Client clock time of the error, which is what a timeline needs.';
COMMENT ON COLUMN "events"."received_at" IS 'Server receipt time. The gap against occurred_at exposes offline buffering and clock skew.';

CREATE INDEX "idx_events_issue_time"
ON "events" ("issue_id", "occurred_at");
CREATE INDEX "idx_events_project_received"
ON "events" ("project_id", "received_at");

CREATE TABLE IF NOT EXISTS "event_stack_frames" (
	-- Owning event. Half of the composite primary key.
	"event_id" BIGINT,
	-- Position in the trace, 0 being the outermost caller. The other half of the key, and the reason frames need no surrogate id.
	"ordinal" SMALLINT,
	-- Source file or module.
	"filename" VARCHAR(500),
	-- Function or method. Null in minified frames that failed to symbolicate.
	"function_name" VARCHAR(500),
	-- Line number after source map resolution.
	"line_no" INTEGER,
	-- Column number, which is what makes a minified JavaScript frame resolvable at all.
	"col_no" INTEGER,
	-- True for frames in the application rather than a dependency. Only in-app frames feed the fingerprint, so a library upgrade that reshuffles its internals does not split one bug into ten issues.
	"in_app" BOOLEAN NOT NULL DEFAULT false,
	-- The source line itself, captured at build time. Stored because the repository may have moved on by the time anyone looks.
	"context_line" TEXT,
	PRIMARY KEY("event_id", "ordinal")
);

COMMENT ON TABLE "event_stack_frames" IS 'The stack trace, one row per frame. Rows rather than a JSON array so the in-app frames that drive grouping and the culprit can be queried directly during ingest.';
COMMENT ON COLUMN "event_stack_frames"."event_id" IS 'Owning event. Half of the composite primary key.';
COMMENT ON COLUMN "event_stack_frames"."ordinal" IS 'Position in the trace, 0 being the outermost caller. The other half of the key, and the reason frames need no surrogate id.';
COMMENT ON COLUMN "event_stack_frames"."filename" IS 'Source file or module.';
COMMENT ON COLUMN "event_stack_frames"."function_name" IS 'Function or method. Null in minified frames that failed to symbolicate.';
COMMENT ON COLUMN "event_stack_frames"."line_no" IS 'Line number after source map resolution.';
COMMENT ON COLUMN "event_stack_frames"."col_no" IS 'Column number, which is what makes a minified JavaScript frame resolvable at all.';
COMMENT ON COLUMN "event_stack_frames"."in_app" IS 'True for frames in the application rather than a dependency. Only in-app frames feed the fingerprint, so a library upgrade that reshuffles its internals does not split one bug into ten issues.';
COMMENT ON COLUMN "event_stack_frames"."context_line" IS 'The source line itself, captured at build time. Stored because the repository may have moved on by the time anyone looks.';

CREATE TABLE IF NOT EXISTS "event_breadcrumbs" (
	-- Owning event. Half of the composite primary key.
	"event_id" BIGINT,
	-- Order within the trail, oldest first. The other half of the key.
	"ordinal" SMALLINT,
	-- navigation | http | console | ui.click | query. Lets the UI collapse the noisy categories by default.
	"category" VARCHAR(64) NOT NULL,
	-- debug | info | warning | error. A breadcrumb can itself be an error that was caught and swallowed.
	"level" VARCHAR(16) NOT NULL DEFAULT 'info',
	-- What happened, already redacted by the SDK.
	"message" VARCHAR(1000),
	-- Category-specific payload such as a status code or a target selector.
	"data" JSONB,
	-- When the breadcrumb was recorded, relative to which the crash is the last entry.
	"occurred_at" TIMESTAMPTZ NOT NULL,
	PRIMARY KEY("event_id", "ordinal")
);

COMMENT ON TABLE "event_breadcrumbs" IS 'The last few dozen things that happened before the crash. They belong to the event and die with it, because a breadcrumb trail is only meaningful for the specific occurrence that produced it.';
COMMENT ON COLUMN "event_breadcrumbs"."event_id" IS 'Owning event. Half of the composite primary key.';
COMMENT ON COLUMN "event_breadcrumbs"."ordinal" IS 'Order within the trail, oldest first. The other half of the key.';
COMMENT ON COLUMN "event_breadcrumbs"."category" IS 'navigation | http | console | ui.click | query. Lets the UI collapse the noisy categories by default.';
COMMENT ON COLUMN "event_breadcrumbs"."level" IS 'debug | info | warning | error. A breadcrumb can itself be an error that was caught and swallowed.';
COMMENT ON COLUMN "event_breadcrumbs"."message" IS 'What happened, already redacted by the SDK.';
COMMENT ON COLUMN "event_breadcrumbs"."data" IS 'Category-specific payload such as a status code or a target selector.';
COMMENT ON COLUMN "event_breadcrumbs"."occurred_at" IS 'When the breadcrumb was recorded, relative to which the crash is the last entry.';

CREATE TABLE IF NOT EXISTS "event_tags" (
	-- Owning event. Half of the composite primary key.
	"event_id" BIGINT,
	-- Tag name such as browser, os, release or customer_id. The other half of the key, so one event carries one value per key.
	"tag_key" VARCHAR(64),
	-- Tag value. Indexed for search, which is the whole reason tags are rows while context stays a JSON blob.
	"tag_value" VARCHAR(255) NOT NULL,
	PRIMARY KEY("event_id", "tag_key")
);

COMMENT ON TABLE "event_tags" IS 'The searchable, faceted slice of an event. Splitting a handful of low-cardinality keys out of the context blob is what makes queries like all events on Safari 17 answerable without scanning JSON.';
COMMENT ON COLUMN "event_tags"."event_id" IS 'Owning event. Half of the composite primary key.';
COMMENT ON COLUMN "event_tags"."tag_key" IS 'Tag name such as browser, os, release or customer_id. The other half of the key, so one event carries one value per key.';
COMMENT ON COLUMN "event_tags"."tag_value" IS 'Tag value. Indexed for search, which is the whole reason tags are rows while context stays a JSON blob.';

CREATE INDEX "idx_event_tags_key_value"
ON "event_tags" ("tag_key", "tag_value");

CREATE TABLE IF NOT EXISTS "issue_assignees" (
	-- Issue being triaged. Half of the composite primary key.
	"issue_id" BIGINT,
	-- Person responsible. The other half of the key, so the same person cannot be assigned twice.
	"user_id" BIGINT,
	-- Who made the assignment. Null for assignment by a code-owners rule.
	"assigned_by_id" BIGINT,
	-- When it was assigned. Drives the reminder for issues sitting untouched.
	"assigned_at" TIMESTAMPTZ NOT NULL DEFAULT now(),
	PRIMARY KEY("issue_id", "user_id")
);

COMMENT ON TABLE "issue_assignees" IS 'Who owns an issue. A join table rather than a column on issues because a crash that spans two services genuinely needs two owners, and because the reverse index is what powers the assigned-to-me view.';
COMMENT ON COLUMN "issue_assignees"."issue_id" IS 'Issue being triaged. Half of the composite primary key.';
COMMENT ON COLUMN "issue_assignees"."user_id" IS 'Person responsible. The other half of the key, so the same person cannot be assigned twice.';
COMMENT ON COLUMN "issue_assignees"."assigned_by_id" IS 'Who made the assignment. Null for assignment by a code-owners rule.';
COMMENT ON COLUMN "issue_assignees"."assigned_at" IS 'When it was assigned. Drives the reminder for issues sitting untouched.';

CREATE INDEX "idx_issue_assignees_user"
ON "issue_assignees" ("user_id", "assigned_at");

CREATE TABLE IF NOT EXISTS "alert_rules" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Owning project.
	"project_id" BIGINT NOT NULL,
	-- What the rule is for, and the subject line of the notification it sends.
	"name" VARCHAR(160) NOT NULL,
	-- new_issue | regression | frequency | user_count. Four distinct questions, so one column instead of four nullable threshold pairs.
	"trigger_kind" VARCHAR(32) NOT NULL,
	-- Occurrences or affected users required to fire. Null for new_issue and regression, which fire on the event itself.
	"threshold" INTEGER,
	-- Rolling window the threshold is measured over. Null for the event-driven kinds.
	"window_minutes" INTEGER,
	-- Lowest issue level that can fire this rule, so warnings do not page anyone.
	"min_level" VARCHAR(16) NOT NULL DEFAULT 'error',
	-- Restricts the rule to one environment. Null means all, which is how a staging deploy pages the on-call unless someone sets this.
	"environment" VARCHAR(64),
	-- email | slack | webhook | pagerduty.
	"channel" VARCHAR(24) NOT NULL DEFAULT 'email',
	-- Channel-specific destination: an address, a channel id, a webhook URL. Opaque to this table by design.
	"target" VARCHAR(500) NOT NULL,
	-- Minimum gap between notifications for the same issue and rule. The difference between an alert and an outage of everyone ignoring alerts.
	"cooldown_minutes" INTEGER NOT NULL DEFAULT 60,
	-- Disabled rather than deleted, so a noisy rule can be silenced without losing its configuration.
	"is_enabled" BOOLEAN NOT NULL DEFAULT true,
	-- Creation time.
	"created_at" TIMESTAMPTZ NOT NULL DEFAULT now(),
	PRIMARY KEY("id")
);

COMMENT ON TABLE "alert_rules" IS 'A condition that turns issue activity into a notification. Thresholds are evaluated against the issue counters rather than by counting events, so alerting keeps working once raw events age out.';
COMMENT ON COLUMN "alert_rules"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "alert_rules"."project_id" IS 'Owning project.';
COMMENT ON COLUMN "alert_rules"."name" IS 'What the rule is for, and the subject line of the notification it sends.';
COMMENT ON COLUMN "alert_rules"."trigger_kind" IS 'new_issue | regression | frequency | user_count. Four distinct questions, so one column instead of four nullable threshold pairs.';
COMMENT ON COLUMN "alert_rules"."threshold" IS 'Occurrences or affected users required to fire. Null for new_issue and regression, which fire on the event itself.';
COMMENT ON COLUMN "alert_rules"."window_minutes" IS 'Rolling window the threshold is measured over. Null for the event-driven kinds.';
COMMENT ON COLUMN "alert_rules"."min_level" IS 'Lowest issue level that can fire this rule, so warnings do not page anyone.';
COMMENT ON COLUMN "alert_rules"."environment" IS 'Restricts the rule to one environment. Null means all, which is how a staging deploy pages the on-call unless someone sets this.';
COMMENT ON COLUMN "alert_rules"."channel" IS 'email | slack | webhook | pagerduty.';
COMMENT ON COLUMN "alert_rules"."target" IS 'Channel-specific destination: an address, a channel id, a webhook URL. Opaque to this table by design.';
COMMENT ON COLUMN "alert_rules"."cooldown_minutes" IS 'Minimum gap between notifications for the same issue and rule. The difference between an alert and an outage of everyone ignoring alerts.';
COMMENT ON COLUMN "alert_rules"."is_enabled" IS 'Disabled rather than deleted, so a noisy rule can be silenced without losing its configuration.';
COMMENT ON COLUMN "alert_rules"."created_at" IS 'Creation time.';

CREATE INDEX "idx_alert_rules_project_enabled"
ON "alert_rules" ("project_id", "is_enabled");

CREATE TABLE IF NOT EXISTS "alert_notifications" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Rule that fired.
	"rule_id" BIGINT NOT NULL,
	-- Issue the alert was about.
	"issue_id" BIGINT NOT NULL,
	-- Rule, issue and cooldown bucket combined. The unique index is the cooldown: a second attempt inside the window fails the insert instead of sending, which survives two workers racing.
	"dedupe_key" VARCHAR(255) NOT NULL UNIQUE,
	-- pending | sent | failed. Retries update the row rather than inserting, so the dedupe key stays the source of truth.
	"status" VARCHAR(16) NOT NULL DEFAULT 'pending',
	-- Delivery failure reason, typically a revoked webhook.
	"error_message" VARCHAR(500),
	-- Delivery time. Null while pending or after a permanent failure.
	"sent_at" TIMESTAMPTZ,
	-- When the rule fired.
	"created_at" TIMESTAMPTZ NOT NULL DEFAULT now(),
	PRIMARY KEY("id")
);

COMMENT ON TABLE "alert_notifications" IS 'One attempted notification. It exists so the product can answer why nobody was told, which is a question asked far more often than why was I told.';
COMMENT ON COLUMN "alert_notifications"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "alert_notifications"."rule_id" IS 'Rule that fired.';
COMMENT ON COLUMN "alert_notifications"."issue_id" IS 'Issue the alert was about.';
COMMENT ON COLUMN "alert_notifications"."dedupe_key" IS 'Rule, issue and cooldown bucket combined. The unique index is the cooldown: a second attempt inside the window fails the insert instead of sending, which survives two workers racing.';
COMMENT ON COLUMN "alert_notifications"."status" IS 'pending | sent | failed. Retries update the row rather than inserting, so the dedupe key stays the source of truth.';
COMMENT ON COLUMN "alert_notifications"."error_message" IS 'Delivery failure reason, typically a revoked webhook.';
COMMENT ON COLUMN "alert_notifications"."sent_at" IS 'Delivery time. Null while pending or after a permanent failure.';
COMMENT ON COLUMN "alert_notifications"."created_at" IS 'When the rule fired.';

CREATE INDEX "idx_alert_notifications_issue"
ON "alert_notifications" ("issue_id", "created_at");

CREATE TABLE IF NOT EXISTS "issue_activity" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Issue that changed.
	"issue_id" BIGINT NOT NULL,
	-- Who acted. Null for automatic transitions, which is how a regression detected by the ingest path is distinguished from someone reopening the issue by hand.
	"actor_id" BIGINT,
	-- resolved | unresolved | ignored | regressed | assigned | unassigned | merged | commented.
	"action" VARCHAR(32) NOT NULL,
	-- Release involved, set on resolve-in-release and on the regression that followed.
	"release_id" BIGINT,
	-- Comment text for the commented action, null otherwise.
	"body" TEXT,
	-- When it happened.
	"created_at" TIMESTAMPTZ NOT NULL DEFAULT now(),
	PRIMARY KEY("id")
);

COMMENT ON TABLE "issue_activity" IS 'Append-only triage history, doubling as the comment thread. Keeping automatic transitions in the same stream as human ones is what makes a regression legible: resolved in 2.1.0, seen again in 2.3.0, reopened by nobody.';
COMMENT ON COLUMN "issue_activity"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "issue_activity"."issue_id" IS 'Issue that changed.';
COMMENT ON COLUMN "issue_activity"."actor_id" IS 'Who acted. Null for automatic transitions, which is how a regression detected by the ingest path is distinguished from someone reopening the issue by hand.';
COMMENT ON COLUMN "issue_activity"."action" IS 'resolved | unresolved | ignored | regressed | assigned | unassigned | merged | commented.';
COMMENT ON COLUMN "issue_activity"."release_id" IS 'Release involved, set on resolve-in-release and on the regression that followed.';
COMMENT ON COLUMN "issue_activity"."body" IS 'Comment text for the commented action, null otherwise.';
COMMENT ON COLUMN "issue_activity"."created_at" IS 'When it happened.';

CREATE INDEX "idx_issue_activity_issue_time"
ON "issue_activity" ("issue_id", "created_at");

